#!/usr/bin/env node
// scripts/science-twins/sci-stwin.mjs — the deterministic half of STRUCTURED science twins
// (SPEC-TWINS §11b). 14 Oct 2026, Adrian: "Aim at the structured questions now, then combined
// science, then the rest of the topics. I will unpause them myself later" → "yes, and those twins
// will be generated by the cloud workers right?" (yes — the Fly worker's science-twins job).
//
// A structured twin is OUR OWN multi-part question modelled on a real school structured row
// filed under a sub-skill: a new situation, new numbers, new sentences; the SAME demand, the same
// parts and the same marks per part; with a mark scheme in the bank's structured shape
// (parts[] {label, text, marks, answer, solution}) that the live practice grader reads
// (lib/practice-grade-prompt collectScheme). The writing is agents (author → blind solve →
// checker, plan-billed `claude -p` / Claude Code agents, never the API); this file does the rest.
// Same modes and file names as sci-twin.mjs, so the lane (bot worker/fly/science-twins.sh) runs
// both with one loop:
//
//   gap      every (pool, topic): servable structured questions (checked school rows + our
//            structured twins) against TARGET (40), and its tier
//   queue    seeds in order [--limit N --json]: tier 1 = the open PURE practice topics
//            (SCIENCE_PRACTICE_OPEN_TOPICS), tier 2 = the open Combined topics, tier 3 = every
//            other topic; inside a tier the thinnest topic first, the topics taking turns; inside a
//            topic the sub-skill with the fewest structured twins first. A topic at TARGET is full.
//   need     --pool P --subgroup S  → how many the sub-skill's TOPIC still wants (0 = full)
//   brief    --source <uuid> --run <dir> --pool P --subgroup S → source.json, corpus.json,
//            plan.json, author-brief.md (+ the seed's figures as seed-fig-N.png for the author)
//   check    --run <dir> → Q1.gates.json; a pass writes Q1.solve.md (blind) + Q1.check.md (checker)
//   publish  --run <dir> [--dry] → the row + its sub-skill filing + practice_difficulty; refuses
//            unless the gates, the blind solve and the checker all passed
//   review   --runs <dir…> --out <file.html> → a phone-width page for Adrian
//
// Env as sci-twin.mjs (SUPABASE_URL_SCIENCE + SUPABASE_SERVICE_KEY_SCIENCE). Never prints a key.
import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { copySeedPartLabels } from '../../src/lib/twin-part-labels.mjs';
import {
  SCI, poolLevels, poolName, parsePool, syllabusOf, SCOPE_WORDS, FORBIDDEN, sb, all, readJsonLoose, readIf,
  grams, jaccard, masked, levelFromWork, openTopics, esc, mdLite,
} from './sci-twin.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const argv = process.argv.slice(2);
const MODE = argv[0] && !argv[0].startsWith('--') ? argv[0] : 'gap';
const argOf = (k, d) => { const i = argv.indexOf(k); return i >= 0 ? argv[i + 1] : d; };
const has = (k) => argv.includes(k);
const log = (s) => console.error(s);

export const TARGET = Number(process.env.SCI_STWINS_TARGET || 40);   // servable structured questions per (pool, topic)
// 18 Oct 2026 (Adrian: "finish math and science up to 3, for long questions too"): with
// SCI_STWINS_PER_SKILL=3 the target is 3 structured twins per (pool, sub-skill) instead of 40
// servable a topic. Off (0) by default, so the Fly lane keeps the topic target until switched.
export const PER_SKILL_S = Number(process.env.SCI_STWINS_PER_SKILL || 0);
const NOVELTY_MAX = 0.4;
const TWIN_SCHOOL = 'AdrianMath';
const PROMPT_VERSION = 'sci-stwin-1';
const BUCKET = 'question_images';
const MCQ_RE = /^\s*([A-Da-d]\s*$|\*\*\(?[A-D]\)?\*\*)/;
const POOLS = ['PHY', 'CHEM', 'BIO', 'CS_PHY', 'CS_CHEM', 'CS_BIO'];
const COLS = 'id,level,subject,school,year,topics,answer,solution,question_text,parts,total_marks,has_image,image_url,images,image_watermark_status,verified,ai_generated,quarantined,not_in_syllabus,practice_hidden,practice_checked_at,practice_check_note,twin_of,exam_type,gen_meta';

/** One structured twin per seed PER POOL (its own key: an MCQ twin of the same seed id cannot clash). */
export const stwinItem = (pool, seed, pass = 1) => `${String(pool).startsWith('CS_') ? `sci-stwin-${pool}-${seed}` : `sci-stwin-${seed}`}${pass > 1 ? `-${pass}` : ''}`;
// 🌱 Short topics (15 Oct 2026, Adrian: "Let one school question seed up to 3 twins, but only for skills
// that are short … do it" → "yes, do all 3"): a topic with fewer fresh seeds than it still wants lets a
// seed that already has a twin in this pool carry a 2nd and 3rd (queued as "<uuid>~2" / "~3"; the lane
// uses it as the run dir + claim name unchanged). The corpus (every row of the topic) already holds the
// earlier twins, so the novelty gate compares against them; brief also puts them in front of the author.
export const SEED_CAP = 3;
export const splitSource = (raw) => { const [id, n] = String(raw ?? '').split('~'); return { id, pass: Math.max(1, Number(n) || 1) }; };
export const flatParts = (ps, pre = '') => (Array.isArray(ps) ? ps : []).flatMap((p) => {
  const label = `${pre}${String(p?.label ?? '').trim()}`;
  const kids = Array.isArray(p?.subparts) && p.subparts.length ? flatParts(p.subparts, `${label}.`) : [];
  if (!kids.length) return [{ ...p, label }];
  // the parent's own text (shared data for its sub-parts) rides on its first sub-part as `lead`
  const lead = [String(p?.text ?? '').trim(), kids[0].lead].filter(Boolean).join('\n');
  return lead ? [{ ...kids[0], lead }, ...kids.slice(1)] : kids;
});
/** lib/science-bank eligible() + the structured filter, in JS (= scripts/science-qcheck servableStructured). */
export function servableStructured(r) {
  return !r.quarantined && (!r.ai_generated || r.verified) && (!r.has_image || r.image_watermark_status === 'clean')
    && !r.not_in_syllabus && !/^gce$/i.test(r.school || '') && r.practice_hidden === false && (r.question_text || '') !== ''
    && (r.answer == null || !MCQ_RE.test(r.answer)) && !!r.solution;
}
const SEED_UNTYPED = /\bplot\b|on the grid|complete (the )?table|\bon (fig|figure|the (diagram|graph))\b[^.]*\b(draw|label|mark|shade|sketch)\b|\b(draw|sketch)\b[^.]*\bon (fig|figure|the (diagram|graph|grid))\b/i;
/** A school structured row we can model a twin on: parts with marks on every leaf, 2–20 marks. */
export function seedUsable(r) {
  if (r.school === TWIN_SCHOOL || !servableStructured(r)) return false;
  const leaves = flatParts(r.parts);
  if (!leaves.length || leaves.some((p) => !(Number(p.marks) >= 1) || !String(p.text ?? '').trim())) return false;
  // a part answered on a grid or a table (plot, complete the table, draw on the figure) has no typed twin of the same demand
  if (leaves.some((p) => SEED_UNTYPED.test(String(p.text)))) return false;
  const tot = leaves.reduce((s, p) => s + Number(p.marks), 0);
  return tot >= 2 && tot <= 20 && String(r.question_text ?? '').length + leaves.reduce((s, p) => s + String(p.text).length, 0) > 60;
}
export const isStructuredTwin = (r) => r.school === TWIN_SCHOOL && r.exam_type === 'Twin' && (r.gen_meta?.kind === 'science-structured-twin' || (r.answer == null && Array.isArray(r.parts) && r.parts.length));

// ------------------------------------------------------------------ data ----
// a network blip is retried (the worker's link drops a long paging run now and then)
async function retry(fn) {
  for (let i = 0; ; i++) {
    try { return await fn(); } catch (e) { if (i >= 3) throw e; await new Promise((r) => setTimeout(r, 2000 * (i + 1))); }
  }
}
async function loadBank() {
  const rows = [];
  for (const subject of ['physics', 'chemistry', 'biology']) {
    // structured rows only (no lettered answer), as lib/science-bank's kind 'structured'
    rows.push(...await retry(() => all(() => sb().from('questions').select(COLS).eq('subject', subject)
      .or('answer.is.null,answer.not.match.^\\s*[A-Da-d]\\s*$').or('answer.is.null,answer.not.match.^\\s*[*][*][A-D][*][*]').order('id'))));
  }
  const filing = [];
  const ids = rows.map((r) => r.id);
  for (let i = 0; i < ids.length; i += 150) {
    const { data, error } = await retry(() => sb().from('question_subgroups').select('question_id, subgroup_id, is_primary').in('question_id', ids.slice(i, i + 150)));
    if (error) throw new Error(error.message);
    filing.push(...(data ?? []));
  }
  const subgroups = await retry(() => all(() => sb().from('subgroups').select('id, name, topic, subject').order('id')));
  let combined = new Set();
  try { combined = new Set((await all(() => sb().from('combined_subskills').select('subgroup_id').order('subgroup_id'))).map((r) => Number(r.subgroup_id))); } catch { /* no view = no filter */ }
  return { rows, filing, subgroups, combined };
}

// Seeds the lane already tried (its marks live on the worker's disk, as for MCQ twins):
// <done>/S-<pool>-<seed>/{parked,published}; a sub-skill given up on: <done>/skip/S-<pool>-<subgroup>.
function triedHere() {
  const dir = argOf('--done-dir', process.env.SCI_TWINS_RUNS_DIR || '/data/science-twins');
  if (!dir || !existsSync(dir)) return { seed: () => false, unit: () => false };
  return {
    // a "~2" seed's folder is "__2" since 18 Oct 2026 (Claude Code refuses writes into "~" folders) — check both names
    seed: (pool, sid) => [sid, String(sid).replace(/~/g, '__')].some((x) => existsSync(join(dir, `S-${pool}-${x}`, 'parked')) || existsSync(join(dir, `S-${pool}-${x}`, 'published'))),
    unit: (pool, sg) => existsSync(join(dir, 'skip', `S-${pool}-${sg}`)),
  };
}

/** Every (pool, topic) with its servable count, tier, need and ordered seeds (one per sub-skill a round). */
export async function topicUnits() {
  const { rows, filing, subgroups, combined } = await loadBank();
  const open = openTopics();
  const isOpen = new Map(open.map((o) => [`${o.pool}|${o.topic}`, o.combined ? 2 : 1]));
  const sgById = new Map(subgroups.map((s) => [Number(s.id), s]));
  const filedBy = new Map();
  for (const f of filing) { const a = filedBy.get(f.question_id) ?? []; a.push(Number(f.subgroup_id)); filedBy.set(f.question_id, a); }
  const tried = triedHere();
  const units = [];
  for (const pool of POOLS) {
    const pp = parsePool(pool); const sci = SCI[pp.key];
    const lv = new Set(poolLevels(pp.key, pp.combined));
    const inPool = rows.filter((r) => r.subject === sci.subject && lv.has(r.level));
    const pure = rows.filter((r) => r.subject === sci.subject && r.level === sci.bank);
    // the topics: the sub-skill tree's topics (Combined: only those the Combined bank has rows in)
    let topics = [...new Set(subgroups.filter((s) => s.subject === sci.subject).map((s) => s.topic))];
    if (pp.combined) { const cs = new Set(inPool.flatMap((r) => r.topics ?? [])); topics = topics.filter((t) => cs.has(t) || isOpen.has(`${pool}|${t}`)); }
    const twinned = new Set(inPool.filter(isStructuredTwin).map((r) => r.twin_of).filter(Boolean));
    const twinsOf = new Map(); for (const r of inPool) if (isStructuredTwin(r) && r.twin_of && !r.practice_hidden) twinsOf.set(r.twin_of, (twinsOf.get(r.twin_of) ?? 0) + 1);
    for (const topic of topics) {
      const ofTopic = inPool.filter((r) => (r.topics ?? []).includes(topic));
      const servable = ofTopic.filter((r) => servableStructured(r) && r.practice_checked_at);
      const twins = ofTopic.filter((r) => isStructuredTwin(r) && !r.practice_hidden);
      const perSkill = new Map();
      for (const t of twins) { const sg = Number(t.gen_meta?.subskill ?? (filedBy.get(t.id) ?? [])[0] ?? 0); perSkill.set(sg, (perSkill.get(sg) ?? 0) + 1); }
      // seeds: a Combined pool prefers the Combined rows themselves, then pure rows; the twin's
      // sub-skill is the seed's filing in THIS topic (Combined: a Combined sub-skill when the view has any)
      const usable = (pp.combined ? [...ofTopic, ...pure.filter((r) => (r.topics ?? []).includes(topic))] : ofTopic).filter(seedUsable);
      const cands = usable.filter((r) => !twinned.has(r.id) && !tried.seed(pool, r.id));
      const skillOf = (r) => {
        let sgs = (filedBy.get(r.id) ?? []).filter((id) => sgById.get(id)?.topic === topic);
        if (pp.combined && combined.size && sgs.some((id) => combined.has(id))) sgs = sgs.filter((id) => combined.has(id));
        const sg = sgs[0];
        return !sg || tried.unit(pool, sg) ? null : sg;
      };
      const bySkill = new Map();
      const seen = new Set();
      for (const r of cands) {
        if (seen.has(r.id)) continue; seen.add(r.id);
        const sg = skillOf(r); if (!sg) continue;
        const a = bySkill.get(sg) ?? []; a.push(r); bySkill.set(sg, a);
      }
      const order = (r) => [r.practice_checked_at ? 0 : 1, r.has_image ? 1 : 0, -(r.year || 0)];
      const cmp = (a, b) => { const x = order(a), y = order(b); for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return x[i] - y[i]; return a.id.localeCompare(b.id); };
      const skills = [...bySkill.entries()].map(([sg, list]) => ({ sg, name: sgById.get(sg)?.name ?? '', twins: perSkill.get(sg) ?? 0, seeds: list.sort(cmp) }))
        .sort((a, b) => a.twins - b.twins || a.name.localeCompare(b.name));
      // one seed per sub-skill a round, the sub-skills with the fewest structured twins first
      const seeds = [];
      for (let round = 0; ; round++) {
        let any = false;
        for (const s of skills) { const r = s.seeds[round]; if (!r) continue; any = true; seeds.push({ source_id: r.id, subgroup_id: s.sg, subgroup: s.name, checked: !!r.practice_checked_at, has_image: !!r.has_image }); }
        if (!any) break;
      }
      if (PER_SKILL_S > 0) {
        // per sub-skill: each short sub-skill offers fresh seeds, then a seed's next twin ("~n"), up to its need
        const reuseOf = new Map();
        const seen3 = new Set();
        for (const r of usable) {
          if (seen3.has(r.id)) continue; seen3.add(r.id);
          const n = twinsOf.get(r.id) ?? 0; if (n < 1 || n >= SEED_CAP || tried.seed(pool, `${r.id}~${n + 1}`)) continue;
          const sg = skillOf(r); if (!sg) continue;
          const a = reuseOf.get(sg) ?? []; a.push({ n, r }); reuseOf.set(sg, a);
        }
        const all = new Set([...bySkill.keys(), ...reuseOf.keys()]);
        const per = [...all].map((sg) => {
          const have = perSkill.get(sg) ?? 0; const need = Math.max(0, PER_SKILL_S - have);
          const fresh = (bySkill.get(sg) ?? []).sort(cmp).map((r) => ({ source_id: r.id, r }));
          const again = (reuseOf.get(sg) ?? []).sort((a, b) => a.n - b.n || cmp(a.r, b.r)).map(({ n, r }) => ({ source_id: `${r.id}~${n + 1}`, r, reuse: n + 1 }));
          return { sg, name: sgById.get(sg)?.name ?? '', have, need, cands: [...fresh, ...again] };
        }).filter((x) => x.need > 0).sort((a, b) => a.have - b.have || a.name.localeCompare(b.name));
        const seedsPS = [];
        for (let round = 0; ; round++) {
          let any = false;
          for (const x of per) { const c = x.cands[round]; if (!c) continue; any = true; seedsPS.push({ source_id: c.source_id, subgroup_id: x.sg, subgroup: x.name, checked: !!c.r.practice_checked_at, has_image: !!c.r.has_image, ...(c.reuse ? { reuse: c.reuse } : {}) }); }
          if (!any) break;
        }
        const needPS = per.reduce((a, x) => a + x.need, 0);
        const writable = per.reduce((a, x) => a + Math.min(x.need, x.cands.length), 0);
        // every sub-skill of the topic with its own need, for `need --subgroup` (asked right before writing)
        const skillNeeds = Object.fromEntries([...new Set([...perSkill.keys(), ...all])].filter(Boolean).map((sg) => [sg, Math.max(0, PER_SKILL_S - (perSkill.get(sg) ?? 0))]));
        units.push({ pool, topic, tier: isOpen.get(`${pool}|${topic}`) ?? 3, servable: servable.length, twins: twins.length, need: needPS, writable, skills_short: per.length, skill_needs: skillNeeds, seed_count: seedsPS.length, seeds: seedsPS });
        continue;
      }
      // 🌱 short of fresh seeds: seeds with 1–2 twins here offer their next one, fewest twins first
      const want = Math.max(0, TARGET - servable.length);
      if (seeds.length < want) {
        const again = []; const seen2 = new Set();
        for (const r of usable) {
          if (seen2.has(r.id)) continue; seen2.add(r.id);
          const n = twinsOf.get(r.id) ?? 0; const next = `${r.id}~${n + 1}`;
          if (n < 1 || n >= SEED_CAP || tried.seed(pool, next)) continue;
          const sg = skillOf(r); if (!sg) continue;
          again.push({ n, r, sg });
        }
        again.sort((a, b) => a.n - b.n || cmp(a.r, b.r));
        for (const { n, r, sg } of again) seeds.push({ source_id: `${r.id}~${n + 1}`, subgroup_id: sg, subgroup: sgById.get(sg)?.name ?? '', checked: !!r.practice_checked_at, has_image: !!r.has_image, reuse: n + 1 });
      }
      units.push({ pool, topic, tier: isOpen.get(`${pool}|${topic}`) ?? 3, servable: servable.length, twins: twins.length, need: Math.max(0, TARGET - servable.length), seed_count: seeds.length, seeds });
    }
  }
  units.sort((a, b) => a.tier - b.tier || a.servable - b.servable || a.pool.localeCompare(b.pool) || a.topic.localeCompare(b.topic));
  return units;
}

/** The queue: tier by tier; inside a tier the topics take turns, thinnest first; never past a topic's need. */
export function queueFromUnits(units, limit) {
  const out = [];
  for (const tier of [1, 2, 3]) {
    const us = units.filter((u) => u.tier === tier && u.need > 0 && u.seeds.length);
    for (let round = 0; out.length < limit; round++) {
      let any = false;
      for (const u of us) {
        if (round >= u.need || !u.seeds[round]) continue;
        any = true;
        if (out.length < limit) out.push({ ...u.seeds[round], pool: u.pool, topic: u.topic, tier, is_open: tier < 3, servable: u.servable, need: u.need });
      }
      if (!any) break;
    }
    if (out.length >= limit) break;
  }
  return out;
}

async function gap() {
  const units = await topicUnits();
  if (has('--json')) { console.log(JSON.stringify({ target: TARGET, units: units.map(({ seeds, ...u }) => u) })); return; }
  if (PER_SKILL_S > 0) {
    for (const tier of [1, 2, 3]) {
      const us = units.filter((u) => u.tier === tier);
      const t = us.reduce((a, u) => ({ skills: a.skills + (u.skills_short ?? 0), need: a.need + u.need, writable: a.writable + (u.writable ?? 0) }), { skills: 0, need: 0, writable: 0 });
      console.log(`${['', 'Tier 1 — open pure topics', 'Tier 2 — open Combined topics', 'Tier 3 — every other topic'][tier]}: ${t.skills} sub-skills short of ${PER_SKILL_S} structured twins · ${t.need} twins needed · ${t.writable} writable from the seeds`);
    }
    return;
  }
  for (const tier of [1, 2, 3]) {
    const us = units.filter((u) => u.tier === tier);
    const need = us.reduce((s, u) => s + u.need, 0);
    console.log(`\n${['', 'Tier 1 — open pure topics', 'Tier 2 — open Combined topics', 'Tier 3 — every other topic'][tier]}: ${us.length} topics, ${need} structured questions short of ${TARGET} each`);
    if (tier < 3 || has('--all')) for (const u of us) console.log(`  ${u.pool.padEnd(8)} ${u.topic.padEnd(42)} servable ${String(u.servable).padStart(3)} · our twins ${String(u.twins).padStart(2)} · wants ${String(u.need).padStart(2)} · seeds ${u.seed_count}`);
  }
}
async function queue() {
  const items = queueFromUnits(await topicUnits(), Number(argOf('--limit', 10)));
  if (has('--json')) { console.log(JSON.stringify(items)); return; }
  for (const r of items) console.log(`${r.source_id}  ${r.pool.padEnd(8)} ${String(r.subgroup_id).padEnd(5)} T${r.tier} ${r.topic} › ${r.subgroup}  (servable ${r.servable}, wants ${r.need})`);
  log(`${items.length} structured seeds`);
}
async function need() {
  const pool = argOf('--pool'); const sg = Number(argOf('--subgroup'));
  if (!parsePool(pool) || !sg) throw new Error('--pool PHY|CHEM|BIO|CS_… --subgroup <id> required');
  const { data: s } = await sb().from('subgroups').select('topic').eq('id', sg).maybeSingle();
  const u = (await topicUnits()).find((x) => x.pool === pool && x.topic === s?.topic);
  // per-skill mode: THIS sub-skill's need (3 − its structured twins), not the whole topic's
  if (PER_SKILL_S > 0) { console.log(u ? (u.skill_needs?.[sg] ?? PER_SKILL_S) : 0); return; }
  console.log(u ? u.need : 0);
}

// ----------------------------------------------------------------- brief ----
function figurePaths(r) {
  const out = [];
  const add = (v) => {
    if (!v) return;
    if (Array.isArray(v)) return v.forEach((e) => add(typeof e === 'string' ? e : e?.url));
    const s = String(v).trim(); if (!s || s === '[]') return;
    if (s.startsWith('[')) { try { return add(JSON.parse(s)); } catch { /* a path */ } }
    out.push(s);
  };
  add(r.image_url); add(r.images);
  for (const p of flatParts(r.parts)) { add(p.image_url); add(p.image_url_after); }
  for (const p of (r.parts ?? [])) { add(p.image_url); }
  const txt = `${r.question_text} ${flatParts(r.parts).map((p) => p.text).join(' ')}`;
  for (const m of txt.matchAll(/\{\{IMG:([^}]+)\}\}|!\[[^\]]*\]\(([^)]+)\)/g)) add(m[1] || m[2]);
  return [...new Set(out)].map((u) => (/^https?:/.test(u) ? u : sb().storage.from(BUCKET).getPublicUrl(u.replace(/^\/+/, '').replace(/^(question_images\/)+/, '')).data.publicUrl));
}
const partLines = (parts, withScheme) => flatParts(parts).map((p) => {
  const head = `${p.lead ? `(${p.label.split('.')[0]}) ${p.lead}\n` : ''}(${p.label}) [${p.marks ?? '?'} mark${Number(p.marks) === 1 ? '' : 's'}] ${String(p.text ?? '').trim()}`;
  if (!withScheme) return head;
  return `${head}\n    Scheme answer: ${String(p.answer ?? '').trim() || '-'}\n    Scheme: ${String(p.solution ?? '').trim().replace(/\n/g, '\n            ') || '-'}`;
}).join('\n');
export const fullText = (q) => `${String(q.stem ?? q.question_text ?? '').trim()}\n${flatParts(q.parts).map((p) => `${p.lead ? `${p.lead}\n` : ''}${String(p.text ?? '')}`).join('\n')}`;

async function brief() {
  const { id, pass } = splitSource(argOf('--source'));
  const dir = resolve(argOf('--run', '.'));
  if (!id) throw new Error('--source <uuid>[~2|~3] required');
  mkdirSync(dir, { recursive: true });
  const { data: src, error } = await sb().from('questions').select('id, level, subject, school, year, exam_type, paper, question_number, question_text, parts, answer, solution, total_marks, topics, skill, has_image, image_url, images').eq('id', id).single();
  if (error) throw new Error(error.message);
  const key = Object.keys(SCI).find((k) => SCI[k].subject === src.subject);
  const pool = argOf('--pool', poolName(key, String(src.level).startsWith('CS_')));
  const pp = parsePool(pool);
  if (!pp) throw new Error(`bad pool ${pool}`);
  const sgId = Number(argOf('--subgroup', 0)) || null;
  const { data: f0 } = await sb().from('question_subgroups').select('subgroup_id').eq('question_id', id);
  const useSg = sgId ?? (f0 ?? [])[0]?.subgroup_id ?? null;
  const { data: sg } = useSg ? await sb().from('subgroups').select('id, name, description, topic').eq('id', useSg).maybeSingle() : { data: null };
  const topic = argOf('--topic', null) ?? sg?.topic ?? (src.topics ?? [])[0];
  const { data: pd } = await sb().from('practice_difficulty').select('level, source, reason').eq('question_id', id).maybeSingle();
  const corpus = await all(() => sb().from('questions').select('id, level, school, year, question_text, parts, twin_of, exam_type, practice_hidden, gen_meta').eq('subject', src.subject).contains('topics', [topic]).neq('id', id).order('id'));
  // the seed's figures, so the author SEES what the seed asks (never copied: a twin's figure is drawn by the library)
  const figs = [];
  for (const [i, u] of figurePaths(src).entries()) {
    try { const r = await fetch(u); if (!r.ok) continue; const f = join(dir, `seed-fig-${i + 1}.png`); writeFileSync(f, Buffer.from(await r.arrayBuffer())); figs.push(f); } catch { /* skip */ }
  }
  // 🌱 the seed's earlier structured twins in this pool (a 2nd / 3rd twin must differ from each)
  const earlier = corpus.filter((r) => r.twin_of === id && r.exam_type === 'Twin' && r.school === TWIN_SCHOOL && !r.practice_hidden && (r.gen_meta?.pool ?? pool) === pool);
  if (pass > 1 && earlier.length >= SEED_CAP) throw new Error(`seed ${id} already has ${earlier.length} twins in ${pool} (cap ${SEED_CAP})`);
  if (pass > 1 && !earlier.length) throw new Error(`seed ${id} has no first twin in ${pool} yet — brief it without ~${pass}`);
  const leaves = flatParts(src.parts);
  const plan = {
    kind: 'structured', source: id, pass, pool, key: pp.key, combined: pp.combined, subject: src.subject, bank_level: pp.combined ? SCI[pp.key].cs : SCI[pp.key].bank, topic,
    subgroups: sg ? [{ id: sg.id, name: sg.name, description: sg.description, is_primary: true }] : [],
    seed_level: ['results', 'estimate'].includes(pd?.source) ? pd.level : null,
    structure: { parts: src.parts.map(function shape(p) { return { label: p.label, marks: p.marks ?? null, ...(Array.isArray(p.subparts) && p.subparts.length ? { subparts: p.subparts.map(shape) } : {}) }; }), leaves: leaves.map((p) => ({ label: p.label, marks: Number(p.marks) })), total: leaves.reduce((s, p) => s + Number(p.marks), 0) },
    syllabus: syllabusOf(pp.key, pp.combined), seed_figures: figs, prompt_version: PROMPT_VERSION,
    models: { author: 'opus (Claude Code agent)', blind: 'opus (fresh Claude Code agent)', checker: 'opus (fresh Claude Code agent)' },
  };
  writeFileSync(join(dir, 'source.json'), JSON.stringify(src, null, 1));
  writeFileSync(join(dir, 'corpus.json'), JSON.stringify(corpus.map((r) => ({ id: r.id, ref: `${r.level} ${r.school} ${r.year}`, text: fullText(r) })), null, 0));
  writeFileSync(join(dir, 'plan.json'), JSON.stringify(plan, null, 1));
  const skillLine = sg ? `${sg.name}${sg.description ? ` — ${sg.description}` : ''}` : '(the seed\'s own skill)';
  const shapeLine = plan.structure.leaves.map((p) => `(${p.label}) ${p.marks}`).join(' · ');
  const md = `# Structured science twin — author brief

You write ONE new STRUCTURED (multi-part) question for Singapore students: OUR OWN question for the
sub-skill below, modelled on the seed. Same demand, same parts, same marks per part — a new
situation, new numbers, new sentences.${pp.combined ? ' It is for **Combined Science** students: write it inside the Combined Science syllabus, even when the seed is from a pure-science paper.' : ''}
Write the file \`${dir}/Q1.json\` and stop.

## The seed (a school's question — never copy it)
- Syllabus: ${plan.syllabus}
- Topic: **${topic}**
- Sub-skill: **${skillLine}**
- Parts and marks you must keep: **${shapeLine}** (total ${plan.structure.total})
${figs.length ? `- The seed has ${figs.length} figure(s): ${figs.map((f) => `\`${f}\``).join(', ')} — open them with the Read tool to see what the seed asks. Never copy or describe them.\n` : ''}
Stem:
\`\`\`
${String(src.question_text ?? '').trim()}
\`\`\`
${earlier.length ? `\n## Earlier twins of this seed — yours must differ from EACH (a new situation, new numbers, new sentences)\n${earlier.map((e, i) => `### Earlier twin ${i + 1}\n\`\`\`\n${fullText(e)}\n\`\`\``).join('\n')}\n` : ''}
Parts with the seed's scheme:
\`\`\`
${partLines(src.parts, true)}
\`\`\`

## What to write
- **Same sub-skill, same demand.** Keep every part's command word (state / describe / explain /
  calculate / suggest / predict…) and the reasoning it wants. Never easier. Not harder by obscure
  facts, long arithmetic or trick wording.
- **Exactly the same parts and marks**: the same labels in the same order (${plan.structure.leaves.map((p) => p.label).join(', ')}), each with the same marks. Sub-parts stay sub-parts.
- **A NEW situation and new numbers.** A teacher holding both must NOT say "that is the seed with
  the numbers changed". Different object, setting, quantities, sentences and order of ideas inside a part.
- **Only ${plan.syllabus} content.**${pp.key === 'PHY' ? ' Physics: NO equations of motion (no suvat, no v = u + at, no v² = u² + 2as) — kinematics is graphs, gradients, areas, average speed, a = (v − u)/t; NO momentum or impulse; NO circular motion; take g = 10 m/s² (or N/kg) and say so when used.' : ''}${pp.key === 'CHEM' ? ' Chemistry: relative atomic masses given in the question when needed (e.g. "Aᵣ: C = 12, O = 16"); a gas volume 24 dm³ per mole at r.t.p. when used.' : ''}${pp.key === 'BIO' ? ' Biology: the syllabus facts and terms as the syllabus words them.' : ''}
- **Every part is answered by TYPING** words, numbers or an equation. No "plot on the grid", no
  "complete the table", no "on Fig. X draw / label", no answer lines to fill. A sketch the
  student can describe in words is fine only when the scheme says exactly what earns each mark.
- **No tables.** Give data in sentences or a short list, one value a line.
- **Self-contained.** No "in the experiment you did", no "your answer to Question 3" (an earlier PART
  of this question is fine: "Use your answer to (b)").
- **Plain words, one idea per sentence.** Units with every quantity. Chemical formulae with Unicode
  subscripts (H₂SO₄, CO₂, Fe²⁺). Maths in $…$ only where it helps.
- **No figure unless the question cannot stand without one.** If it needs one, it must be drawn by
  the bot's figure library from a spec (families: free-body-diagram, moments-lever, circuit-diagram,
  ray-diagram, speed-time, chem-apparatus, chem-graph, chem-energy-profile, chem-dot-cross,
  chem-electron-shells, chem-structure, measuring-instrument, function-graph, coordinate-plane):
  read the family's spec language first with \`node ${ROOT}/scripts/gce-paper/figure.mjs --doc <family>\`,
  then write \`${dir}/Q1.figure.json\` as \`{"family": "...", "spec": {...}}\`. Refer to it as "the diagram".
  No family can draw it? Set "needs_figure": true, leave Q1.figure.json out, and add
  "figure_need": {"what": "one plain line: the picture the question needs", "shape": "short-kebab-name"}.
  Better still: choose a situation that needs no picture.
- Never name a school, a year, an exam paper, a source, or any computer program in anything a student reads.

## The mark scheme (house style — the live grader marks a student's typed answer against it)
For EACH part:
- \`answer\`: the final answer in one short line (a value with its unit, a named substance, the key
  point). For an explain part, the key points joined with "; ".
- \`solution\`: the scheme, **one mark point a line**, each line ending with its mark code in
  brackets: \`(B1)\` an independent mark, \`(M1)\` a method mark, \`(A1)\` an accuracy mark that
  needs the method, \`(C1)\` a compensation mark. The codes of a part add up to its marks exactly —
  or, when the scheme lists more creditable points than marks, say so on the first line: "Any 2 of:".
  Working is a chain, one step a line, units kept. Then \`**Answer:** …\` (no code) — only grader notes ("Accept: …", "Do not accept: …", "Award …") may follow it.
  Accept-alternatives go on their own line(s) AFTER the **Answer:** line: "Accept: …".
- **Credit every correct answer a good student might give** — the checker fails a scheme that would
  not credit one, even if nobody gave it (the commonest reason a twin is dropped): equivalent terms,
  an ionic AND a full equation, a correct alternative method, every other valid point or factor.
  Put them on "Accept: …" lines. Make the data lead to ONE answer (check charges balance, totals add).
- No examiner chat ("candidates often…"), no "Mark scheme:" heading.

## Q1.json — exactly this shape
\`\`\`json
{
  "stem": "the shared information, before part (a) — may be short",
  "parts": [
    { "label": "a", "text": "the part's question", "marks": 2,
      "answer": "6.0 m/s²",
      "solution": "$a = \\\\frac{v - u}{t}$ (M1)\\n$= \\\\frac{12 - 0}{2.0} = 6.0$ m/s² (A1)\\n**Answer:** 6.0 m/s²" },
    { "label": "b", "text": "…", "marks": 1, "answer": "…", "solution": "… (B1)\\n**Answer:** …" }
  ],
  "why_level": "what makes it as demanding as the seed (the ideas joined, the step), one or two lines",
  "originality_note": "how it differs from the seed: situation, numbers, order of ideas",
  "needs_figure": false
}
\`\`\`
(Sub-parts, if the seed has them: \`{"label": "b", "text": "…", "subparts": [{"label": "i", …}, {"label": "ii", …}]}\` — marks/answer/solution on the sub-parts.)
`;
  writeFileSync(join(dir, 'author-brief.md'), md);
  log(`brief → ${dir} (${pool} · ${topic} · ${sg?.name ?? 'no sub-skill'} · ${shapeLine} · corpus ${corpus.length} · seed figures ${figs.length})`);
}

// ----------------------------------------------------------------- check ----
const CODE_RE = /[([]\s*([BMAC])\s*(\d)\s*[)\]]/g;   // (B1) as the brief asks; [B1] (the bank's older form) counts too
const GRADER_NOTE = /^(accept|do not|don't|reject|award|ignore|allow|not|no mark|max(imum)?\b)/i;
const TYPED_ONLY = [/\bplot\b/i, /on the grid/i, /complete the table/i, /\bon (fig|figure|the diagram)\b[^.]*\b(draw|label|mark|shade)/i, /\b(draw|label|mark|shade)\b[^.]*\bon (fig|figure|the diagram)\b/i, /\bfig(ure)?\.?\s*\d/i, /answer lines?/i];
export function gateStructured(q, { src, corpus = [], key, structure }) {
  const problems = [];
  const leaves = flatParts(q.parts);
  if (!Array.isArray(q.parts) || !leaves.length) problems.push('no parts');
  const text = fullText(q);
  if (text.length < 60) problems.push('question too short');
  // the seed's shape: same labels in the same order, same marks
  const want = structure?.leaves ?? [];
  const got = leaves.map((p) => String(p.label).trim());
  if (want.length && got.join('|') !== want.map((p) => p.label).join('|')) problems.push(`parts must be ${want.map((p) => `(${p.label})`).join(' ')} like the seed — got ${got.map((l) => `(${l})`).join(' ') || 'none'}`);
  const totalMarks = leaves.reduce((s, p) => s + (Number(p.marks) || 0), 0);
  for (const [i, p] of leaves.entries()) {
    const L = `(${p.label})`;
    if (String(p.text ?? '').trim().length < 8) problems.push(`${L} has no question text`);
    if (!Number.isInteger(Number(p.marks)) || Number(p.marks) < 1) problems.push(`${L} marks must be a whole number ≥ 1`);
    else if (want[i] && Number(p.marks) !== Number(want[i].marks)) problems.push(`${L} has ${p.marks} mark(s); the seed's (${want[i].label}) has ${want[i].marks}`);
    if (!String(p.answer ?? '').trim()) problems.push(`${L} has no "answer"`);
    const sol = String(p.solution ?? '');
    if (!sol.trim()) { problems.push(`${L} has no "solution" (scheme)`); continue; }
    // codes are counted on the mark-point lines only (an "Accept: …" line may repeat codes for an alternative route)
    const codes = sol.split('\n').map((l) => l.trim()).filter((l) => l && !GRADER_NOTE.test(l) && !/^\*\*Answer:/.test(l))
      .reduce((n, l) => n + [...l.matchAll(CODE_RE)].reduce((s, m) => s + Number(m[2]), 0), 0);
    const anyOf = /\bany\s+\d+\b|\bmax(imum)?\b/i.test(sol);
    if (codes < Number(p.marks)) problems.push(`${L} scheme codes add to ${codes}, the part has ${p.marks} mark(s) — one mark code per mark point`);
    else if (codes > Number(p.marks) && !anyOf) problems.push(`${L} scheme codes add to ${codes} but the part has ${p.marks} — trim, or open with "Any ${p.marks} of:"`);
    const lines = sol.split('\n').map((l) => l.trim()).filter(Boolean);
    // grader notes may follow the Answer line: "Accept: …", "Do not accept: …", "Reject: …", "Award …", "Ignore …"
    const tail = lines.filter((l) => !GRADER_NOTE.test(l));
    if (!/^\*\*Answer:\*\*/.test(tail[tail.length - 1] ?? '')) problems.push(`${L} scheme must end with a "**Answer:** …" line (only "Accept: / Do not accept: / Reject: / Award …" notes after it)`);
    if (lines.some((l) => l.length > 260)) problems.push(`${L} scheme has a line over 260 characters — one point a line`);
    if (/mark scheme:|candidates (often|should|must)|examiner/i.test(sol)) problems.push(`${L} scheme carries examiner commentary`);
  }
  if (structure?.total && totalMarks !== structure.total) problems.push(`total ${totalMarks} marks; the seed has ${structure.total}`);
  const everything = `${text}\n${leaves.map((p) => `${p.answer ?? ''}\n${p.solution ?? ''}`).join('\n')}`;
  for (const re of FORBIDDEN) if (re.test(everything)) problems.push(`names something a student must never read (${re})`);
  for (const re of SCOPE_WORDS[key] ?? []) if (re.test(everything)) problems.push(`out of the syllabus scope (${re})`);
  for (const re of TYPED_ONLY) if (re.test(text)) problems.push(`a part cannot be answered by typing, or names a figure that is not ours (${re})`);
  if (text.split('\n').some((l) => /^\s*\|/.test(l))) problems.push('a table in the question — give the data in sentences or a list');
  if (q.needs_figure !== true && /\b(the )?(diagram|figure) (below|above|shows)\b|\b(graph|table) (below|above)\b/i.test(text)) problems.push('the text refers to a diagram but needs_figure is false');
  const g = grams(text);
  const srcText = fullText(src);
  const vsSource = Number(jaccard(g, grams(srcText)).toFixed(3));
  let nearest = null, nearestS = 0, nearestId = null;
  for (const r of corpus) { const s = jaccard(g, grams(r.text)); if (s > nearestS) { nearestS = s; nearest = r.ref; nearestId = r.id; } }
  nearestS = Number(nearestS.toFixed(3));
  if (vsSource > NOVELTY_MAX) problems.push(`too close to the seed (trigram Jaccard ${vsSource} > ${NOVELTY_MAX})`);
  if (nearestS > NOVELTY_MAX) problems.push(`too close to a bank question ${nearest} (trigram Jaccard ${nearestS} > ${NOVELTY_MAX})`);
  const m = masked(text);
  const numberSwap = m === masked(srcText) || corpus.some((r) => masked(r.text) === m);
  if (numberSwap) problems.push('number-swap: with the numbers masked it is the same as a bank question');
  // part by part: a part whose wording (numbers masked) is the seed's part is a swap too
  const srcParts = new Set(flatParts(src.parts).map((p) => masked(p.text)).filter((t) => t.length > 25));
  const sameParts = leaves.filter((p) => srcParts.has(masked(p.text))).length;
  if (sameParts >= Math.max(2, Math.ceil(leaves.length / 2))) problems.push(`${sameParts} parts are the seed's parts with numbers changed — new wording, please`);
  return { pass: problems.length === 0, problems, total_marks: totalMarks, novelty: { vs_source: vsSource, nearest, nearest_id: nearestId, nearest_jaccard: nearestS, max: NOVELTY_MAX, number_swap: numberSwap, same_parts: sameParts } };
}

function check() {
  const dir = resolve(argOf('--run', '.'));
  const plan = JSON.parse(readFileSync(join(dir, 'plan.json'), 'utf8'));
  const src = JSON.parse(readFileSync(join(dir, 'source.json'), 'utf8'));
  const corpus = JSON.parse(readFileSync(join(dir, 'corpus.json'), 'utf8'));
  const prev = readIf(join(dir, 'Q1.gates.json'), false) ?? {};
  const q = readJsonLoose(join(dir, 'Q1.json'));
  const res = gateStructured(q, { src, corpus, key: plan.key, structure: plan.structure });
  let figure = null;
  if (q.needs_figure === true) {
    if (!existsSync(join(dir, 'Q1.figure.json')) && !existsSync(join(dir, 'Q1.figure.cjs'))) res.problems.push('needs_figure but no Q1.figure.json');
    else {
      const r = spawnSync(process.execPath, [join(ROOT, 'scripts/gce-paper/figure.mjs'), '--run', dir, '--slots', '1'], { encoding: 'utf8' });
      figure = { rc: r.status, out: String(r.stdout || r.stderr || '').slice(-400) };
      if (!existsSync(join(dir, 'Q1.figure.png'))) res.problems.push(`figure did not render: ${figure.out.replace(/\s+/g, ' ').slice(-200)}`);
    }
  }
  res.pass = res.problems.length === 0;
  const gates = { ...res, figure, checked_at: new Date().toISOString(), rounds: (prev.rounds ?? 0) + 1 };
  writeFileSync(join(dir, 'Q1.gates.json'), JSON.stringify(gates, null, 1));
  if (gates.pass) {
    const figLine = q.needs_figure ? `\nThe question has a diagram: open \`${dir}/Q1.figure.png\` with the Read tool and use it.\n` : '';
    const labels = flatParts(q.parts).map((p) => p.label);
    writeFileSync(join(dir, 'Q1.solve.md'), `# Blind solve — structured question

You are the strongest candidate sitting ${plan.syllabus}. Answer every part of this structured
question in full, exactly as you would to earn every mark — the precise term, the working with
units, the cause → effect chain. You have NOT seen the setter's scheme. Then write
\`${dir}/Q1.blind.json\`:

\`\`\`json
{ "parts": [ ${labels.map((l) => `{ "label": "${l}", "answer": "your full answer to (${l}), as you would write it", "final": "the final value / key point in one line" }`).join(',\n             ')} ],
  "confidence": 0.0-1.0,
  "issues": ["anything unclear, ambiguous, wrong, unanswerable by typing or out of syllabus — or empty"] }
\`\`\`
${figLine}
## The question

${String(q.stem ?? '').trim()}

${partLines(q.parts, false)}
`);
    const near = gates.novelty.nearest_id ? corpus.find((r) => r.id === gates.novelty.nearest_id) : null;
    writeFileSync(join(dir, 'Q1.check.md'), `# Checker — one structured science twin

You are a senior ${plan.syllabus} examiner checking OUR OWN structured practice question before any
student sees it. A student types an answer to each part; a grader marks it against the scheme
below and nothing else; then the student reads the scheme. Read this file, then the blind
solver's answers in \`${dir}/Q1.blind.json\`${q.needs_figure ? ` and the diagram \`${dir}/Q1.figure.png\`` : ''}.
Work every part yourself first. Then write \`${dir}/Q1.verdict.json\` and stop.

## The twin (with the setter's scheme)
${String(q.stem ?? '').trim()}

${partLines(q.parts, true)}

Setter's notes — why this level: ${q.why_level ?? '-'}; originality: ${q.originality_note ?? '-'}

## What it is modelled on (the seed, a school's question — same parts and marks)
Topic ${plan.topic} · sub-skill ${plan.subgroups.map((s) => s.name).join(', ') || '-'}
\`\`\`
${String(src.question_text ?? '').trim()}

${partLines(src.parts, true)}
\`\`\`

## The nearest bank question by wording (trigram Jaccard ${gates.novelty.nearest_jaccard})
\`\`\`
${near ? String(near.text).slice(0, 1200) : '(none)'}
\`\`\`

## Judge every point (false on any = the twin is NOT published)
1. scheme_correct — every part's scheme answer is right (do every calculation; check every fact).
2. blind_agrees — the blind solver reached the scheme's answer / key points on EVERY part. Mark the
   blind answers with the scheme as the grader would: blind_marks = the marks they earn. A strong,
   correct blind answer that the scheme would NOT credit means the scheme is too narrow → false.
3. scheme_markable — a grader holding only this scheme can mark a typed answer: each mark point is
   one clear idea or value, the codes add to the part's marks (or "Any N of:" is stated), units and
   accept-alternatives where needed. A DIFFERENT correct answer a good student might give that the
   scheme leaves out and a grader holding it would refuse (a second valid similarity or factor, an
   ionic equation where only the full one is listed, a correct alternative method) makes this
   false — even when the blind solver happened not to give it; put the missing "Accept: …" in
   fixes. The grader already credits the same point in other words or with the data quoted, so a
   rewording of a listed point is NOT a reason for false.
4. one_reading — every part has one sensible reading and one defensible answer (the blind solver's "issues").
5. typed_answerable — every part can be answered fully by typing (no grid, table or drawing on a figure).
6. self_contained — all data needed is given; nothing refers to an experiment or question the student has not seen.
7. in_syllabus — everything needed is in ${plan.syllabus}.${plan.key === 'PHY' ? ' No equations of motion, no momentum, no circular motion.' : ''}
8. original — not the seed (or the nearest question) with numbers or nouns swapped. reads_as_source = true if a teacher holding both would call it the same question.
9. same_skill — it exercises the seed's sub-skill; same_demand — the same parts, marks and command words, and each part asks for the same kind of thinking as the seed's.
10. level — work_score 1–5 as the estimator rates it (1–2 Core, 3 Exam, 4–5 Challenge); level_ok = at least as demanding as the seed, and any difficulty is for a good reason.
11. house_style — one mark point a line with its code, working one step a line, units kept, each part ends with **Answer:**; plain short words; no examiner chat.
12. student_safe — nothing names a school, a year, a paper or a computer program; the facts are right.

\`\`\`json
{ "scheme_correct": true, "blind_agrees": true, "blind_marks": ${gates.total_marks}, "total_marks": ${gates.total_marks},
  "scheme_markable": true, "one_reading": true, "typed_answerable": true, "self_contained": true,
  "in_syllabus": true, "original": true, "reads_as_source": false, "same_skill": true, "same_demand": true,
  "work_score": 3, "level_ok": true, "house_style": true, "student_safe": true,
  "per_part": [ ${labels.map((l) => `{ "label": "${l}", "blind_marks": 0, "note": "" }`).join(', ')} ],
  "score": 1-5, "why": "one or two lines", "fixes": ["a concrete fix per failed point — or empty"] }
\`\`\`
`);
  }
  console.log(gates.pass ? `gates ✓ (vs seed ${gates.novelty.vs_source}, nearest ${gates.novelty.nearest_jaccard})` : `gates ✗\n- ${gates.problems.join('\n- ')}`);
  if (!gates.pass) process.exitCode = 1;
}

/** Every point true, the blind solve earning all (≤ 3 marks) or all but one of the marks, score ≥ 4. */
export function verdictOk(v, blind, total) {
  if (!v || !blind || !Array.isArray(blind.parts) || !blind.parts.length) return false;
  const tot = Number(total) || Number(v.total_marks) || 0;
  const bm = Number(v.blind_marks);
  const enough = Number.isFinite(bm) && tot > 0 && bm >= (tot <= 3 ? tot : tot - 1);
  return enough && ['scheme_correct', 'blind_agrees', 'scheme_markable', 'one_reading', 'typed_answerable', 'self_contained', 'in_syllabus', 'original', 'same_skill', 'same_demand', 'level_ok', 'house_style', 'student_safe'].every((k) => v[k] === true)
    && v.reads_as_source !== true && Number(v.work_score) >= 1 && Number(v.work_score) <= 5 && Number(v.score) >= 4;
}

// --------------------------------------------------------------- publish ----
export const partsForBank = (parts) => parts.map((p) => {
  const out = { label: String(p.label).trim(), text: String(p.text ?? '').trim() };
  if (Array.isArray(p.subparts) && p.subparts.length) out.subparts = partsForBank(p.subparts);
  else { out.marks = Number(p.marks); out.answer = String(p.answer ?? '').trim(); out.solution = String(p.solution ?? '').trim(); }
  return out;
});
export const wholeScheme = (parts) => flatParts(parts).map((p) => `(${p.label}) ${String(p.solution ?? '').trim()}`).join('\n\n');

async function publish() {
  const dir = resolve(argOf('--run', '.'));
  const dry = has('--dry');
  const plan = JSON.parse(readFileSync(join(dir, 'plan.json'), 'utf8'));
  const src = JSON.parse(readFileSync(join(dir, 'source.json'), 'utf8'));
  const q = readJsonLoose(join(dir, 'Q1.json'));
  const gates = readIf(join(dir, 'Q1.gates.json'), false);
  const blind = readIf(join(dir, 'Q1.blind.json'));
  const verdict = readIf(join(dir, 'Q1.verdict.json'));
  if (!gates?.pass) throw new Error('gates not passed — run check first');
  // the gates are re-run on the file as it is now (a hand edit after check must pass again)
  const again = gateStructured(q, { src, corpus: JSON.parse(readFileSync(join(dir, 'corpus.json'), 'utf8')), key: plan.key, structure: plan.structure });
  if (!again.pass) throw new Error(`gates fail on the current Q1.json: ${again.problems.join('; ')}`);
  if (!verdictOk(verdict, blind, gates.total_marks)) throw new Error(`refused: verdict ${JSON.stringify(verdict ?? null).slice(0, 400)}`);
  const png = join(dir, 'Q1.figure.png');
  if (q.needs_figure && !existsSync(png)) throw new Error('needs_figure but Q1.figure.png is not rendered');
  const item = stwinItem(plan.pool, plan.source, Number(plan.pass) || 1);
  const level = plan.seed_level ?? levelFromWork(verdict.work_score);
  const label = { core: 'Core', exam: 'Exam', challenge: 'Challenge' }[level];
  const imagePath = q.needs_figure ? `twins/${item}.png` : null;
  const figSpec = existsSync(join(dir, 'Q1.figure.json')) ? JSON.parse(readFileSync(join(dir, 'Q1.figure.json'), 'utf8')) : null;
  const now = new Date().toISOString();
  const parts = partsForBank(q.parts);
  const row = {
    level: plan.bank_level, subject: plan.subject, school: TWIN_SCHOOL, year: new Date().getFullYear(), exam_type: 'Twin',
    paper: null, question_number: null,
    question_text: String(q.stem ?? '').trim(), parts, answer: null, solution: wholeScheme(parts), solution_source: 'opus_session',
    topics: [plan.topic], skill: null, difficulty: level === 'challenge' ? 'Challenging' : 'Standard', total_marks: gates.total_marks,
    has_image: !!imagePath, image_url: imagePath, images: [], image_size: 'md',
    image_watermark_status: null,   // a drawn figure waits for the science figure check (bot figfit) to stamp 'clean'
    verified: true, ai_generated: true, twin_of: plan.source, source_question_id: null,
    quarantined: false, not_in_syllabus: false, practice_hidden: false,
    practice_checked_at: now, practice_check_note: 'structured twin: every check passed (gates, blind solve, checker)',
    gen_meta: {
      kind: 'science-structured-twin', twin_item: item, twin_of: plan.source, prompt_version: PROMPT_VERSION, pool: plan.pool, level_written: level, subskill: plan.subgroups?.[0]?.id ?? null,
      source_ref: { school: src.school, year: src.year, paper: src.paper ?? null, question_number: src.question_number ?? null },
      models: plan.models, gates: { novelty: gates.novelty, rounds: gates.rounds },
      blind: { finals: blind.parts.map((p) => ({ label: p.label, final: p.final ?? null })), confidence: blind.confidence ?? null, issues: blind.issues ?? [] },
      verdict: { work_score: verdict.work_score, score: verdict.score, blind_marks: verdict.blind_marks, why: verdict.why },
      why_level: q.why_level ?? null, originality_note: q.originality_note ?? null,
      figure: imagePath ? { family: figSpec?.family ?? null, spec: figSpec?.spec ?? figSpec } : null,
      subgroups: (plan.subgroups ?? []).map((s) => s.id), generated_at: now, verified_by: 'checks',
    },
  };
  if (dry) { console.log(JSON.stringify(row, null, 1)); return; }
  if ((Number(plan.pass) || 1) > 1) {   // 🌱 never past SEED_CAP live twins of one seed in a pool
    const { data: live } = await sb().from('questions').select('id, gen_meta').eq('twin_of', plan.source).eq('school', TWIN_SCHOOL).eq('exam_type', 'Twin').eq('practice_hidden', false);
    const here = (live ?? []).filter((r) => (r.gen_meta?.pool ?? plan.pool) === plan.pool);
    if (!here.some((r) => r.gen_meta?.twin_item === item) && here.length >= SEED_CAP) throw new Error(`seed ${plan.source} already has ${here.length} twins in ${plan.pool} (cap ${SEED_CAP})`);
  }
  if (imagePath) {
    const { error } = await sb().storage.from(BUCKET).upload(imagePath, readFileSync(png), { contentType: 'image/png', upsert: true });
    if (error) throw new Error(`figure upload: ${error.message}`);
  }
  const { data: existing } = await sb().from('questions').select('id').eq('gen_meta->>twin_item', item).limit(1);
  let qid;
  if (existing?.length) {
    qid = existing[0].id;
    const { error } = await sb().from('questions').update(row).eq('id', qid);
    if (error) throw new Error(error.message);
  } else {
    const { data, error } = await sb().from('questions').insert(row).select('id').single();
    if (error) throw new Error(error.message);
    qid = data.id;
  }
  const filing = (plan.subgroups ?? []).map((s) => ({ question_id: qid, subgroup_id: s.id, is_primary: true, confidence: 1, source: 'twin', reason: `structured science twin of ${plan.source}` }));
  if (filing.length) { const { error } = await sb().from('question_subgroups').upsert(filing, { onConflict: 'question_id,subgroup_id' }); if (error) log(`filing warning: ${error.message}`); }
  // the seed's PART skills too, when its parts line up (SPEC-PART-SKILLS.md §Twins); else the filer's re-tag labels it
  const pl = await copySeedPartLabels(sb(), qid, plan.source);
  if (pl.copied) log(`part skills: ${pl.copied} copied from the seed`);
  const { error: pdErr } = await sb().from('practice_difficulty').upsert({
    question_id: qid, level, source: 'twin', attempts: 0, wrong: 0, wrong_share: null,
    work_score: verdict.work_score, test_solve: null, reason: `Our own ${label} structured question; ${String(q.why_level ?? verdict.why ?? '').slice(0, 200)}`,
    detail: { twin_of: plan.source, checker_score: verdict.score, kind: 'structured' }, updated_at: now,
  }, { onConflict: 'question_id' });
  if (pdErr) throw new Error(`practice_difficulty: ${pdErr.message}`);
  writeFileSync(join(dir, 'published.json'), JSON.stringify({ id: qid, item, at: now }, null, 1));
  console.log(`${existing?.length ? 'updated' : 'inserted'} ${qid} (structured science twin of ${plan.source}, ${plan.pool}, ${label})`);
}

// ---------------------------------------------------------------- review ----
function review() {
  const dirs = [];
  const i = argv.indexOf('--runs');
  for (let k = i + 1; i >= 0 && k < argv.length && !argv[k].startsWith('--'); k++) dirs.push(resolve(argv[k]));
  const out = resolve(argOf('--out', 'structured-twins-review.html'));
  const withSeed = has('--with-seed');
  const scheme = (s) => mdLite(s).replace(/[([]([BMAC]\d)[)\]]/g, '<span class="code">$1</span>');
  const cards = dirs.map((dir, n) => {
    const plan = readIf(join(dir, 'plan.json'), false); const src = readIf(join(dir, 'source.json'), false);
    const q = existsSync(join(dir, 'Q1.json')) ? readJsonLoose(join(dir, 'Q1.json')) : null;
    const v = readIf(join(dir, 'Q1.verdict.json')); const b = readIf(join(dir, 'Q1.blind.json')); const g = readIf(join(dir, 'Q1.gates.json'), false);
    if (!plan || !q) return '';
    const ok = g?.pass && verdictOk(v, b, g?.total_marks);
    const fig = q.needs_figure && existsSync(join(dir, 'Q1.figure.png')) ? `<img class="fig" src="data:image/png;base64,${readFileSync(join(dir, 'Q1.figure.png')).toString('base64')}">` : '';
    const subj = { physics: 'Physics', chemistry: 'Chemistry', biology: 'Biology' }[plan.subject];
    const parts = flatParts(q.parts).map((p) => `${p.lead ? `<div class="part"><div class="pq"><b>(${esc(p.label.split('.')[0])})</b> ${mdLite(p.lead)}</div></div>` : ''}<div class="part"><div class="pq"><b>(${esc(p.label)})</b> ${mdLite(p.text)} <span class="mk">[${esc(p.marks)}]</span></div>
<details><summary>Answer guide</summary><div class="sol">${scheme(p.solution)}</div></details></div>`).join('');
    return `<section class="card ${ok ? 'ok' : 'no'}">
<div class="meta"><span class="pill ${plan.subject}">${plan.combined ? 'Combined · ' : ''}${subj}</span> <span>${esc(plan.topic)}</span> <span class="lvl">${esc((plan.subgroups?.[0]?.name) ?? '')}</span></div>
<div class="n">${n + 1}</div>
<div class="q">${mdLite(q.stem)}</div>${fig}${parts}
<div class="checks">${ok ? '✓ every check passed' : '✗ not passed'} · blind solve ${esc(v?.blind_marks ?? '–')}/${esc(g?.total_marks ?? '–')} marks · checker ${esc(v?.score ?? '–')}/5 · work ${esc(v?.work_score ?? '–')}/5 · wording overlap ${g?.novelty?.vs_source ?? '–'} (seed), ${g?.novelty?.nearest_jaccard ?? '–'} (nearest)</div>
${withSeed ? `<details class="seed"><summary>Modelled on (a school question — never shown to students)</summary><div class="q">${mdLite(src.question_text)}<br>${flatParts(src.parts).map((p) => `${p.lead ? `${mdLite(p.lead)}<br>` : ''}<b>(${esc(p.label)})</b> ${mdLite(p.text)} [${esc(p.marks)}]`).join('<br>')}</div></details>` : ''}
</section>`;
  }).join('\n');
  // the KaTeX stylesheet inlined (a published review page may load scripts from a CDN but no stylesheet); its fonts fall back
  let katexCss = '';
  try { katexCss = readFileSync(join(ROOT, 'node_modules/katex/dist/katex.min.css'), 'utf8').replace(/@font-face\{[^}]*\}/g, ''); } catch { /* no katex: maths shows as text */ }
  const html = `<title>Structured science twins</title>
<style>${katexCss}</style>
<script defer src="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.11/katex.min.js"></script>
<script defer src="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.11/contrib/auto-render.min.js" onload="renderMathInElement(document.body,{delimiters:[{left:'$',right:'$',display:false}]})"></script>
<style>
:root{--bg:#f6f5f1;--card:#fff;--ink:#1d1d1f;--mute:#6b6b70;--line:#e3e1da;--ok:#1f7a4d;--no:#b3261e}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#141416;--card:#1e1e21;--ink:#ececf0;--mute:#9a9aa2;--line:#2e2e33}}
:root[data-theme="dark"]{--bg:#141416;--card:#1e1e21;--ink:#ececf0;--mute:#9a9aa2;--line:#2e2e33}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 -apple-system,system-ui,sans-serif}
main{max-width:560px;margin:0 auto;padding:16px}
h1{font-size:20px;margin:8px 0 4px}.sub{color:var(--mute);font-size:14px;margin:0 0 16px}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px 16px;margin:0 0 14px;position:relative;overflow-wrap:anywhere}
.card.no{border-color:var(--no)}
.meta{display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:13px;color:var(--mute);margin-bottom:8px;padding-right:28px}
.pill{border-radius:99px;padding:2px 9px;font-weight:600;color:#fff}.physics{background:#2f6fb5}.chemistry{background:#8a4fbf}.biology{background:#2e8b57}
.lvl{font-weight:600;color:var(--ink)}.n{position:absolute;top:12px;right:14px;color:var(--mute);font-size:13px}
.q{margin:4px 0 10px}.fig{max-width:100%;height:auto;display:block;margin:6px auto 10px;background:#fff;border-radius:8px}
.part{border-top:1px solid var(--line);padding:8px 0 4px}.mk{color:var(--mute);font-size:14px;white-space:nowrap}
.code{font-size:11px;color:var(--mute);border:1px solid var(--line);border-radius:4px;padding:0 3px;margin-left:4px}
details{margin:4px 0}summary{cursor:pointer;color:var(--mute);font-size:14px}.sol{margin-top:6px;font-size:15px}
.checks{font-size:12px;color:var(--mute);margin-top:8px}.seed .q{font-size:14px;color:var(--mute)}
</style><main><h1>Structured science twins — ${dirs.length} samples</h1>
<p class="sub">Our own structured questions, each modelled on a school question of the same sub-skill, with the same parts and marks. Tap "Answer guide" under a part to see what earns each mark.</p>
${cards}</main>`;
  writeFileSync(out, html);
  console.log(`review → ${out}`);
}

const MODES = { gap, queue, need, brief, check, publish, review };
if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  if (!MODES[MODE]) { log(`modes: ${Object.keys(MODES).join(' · ')}`); process.exit(2); }
  Promise.resolve(MODES[MODE]()).catch((e) => { log(`sci-stwin ${MODE}: ${e.message}`); process.exit(1); });
}
